import json,hashlib
from pathlib import Path
G=Path(r'C:\Github\DecenniumDescent'); R=G/'DescentReviewChanges/ReviewBible'; A=G/'docs/audit/2026-10-08/full-game'; D=R/'data/playtest/spell_drafts'
read=lambda p:json.loads(p.read_text(encoding='utf-8'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
src={s['id']:s for s in read(D/'candidate_divination_rank3_sources.json')['spells']}
review='docs/audit/2026-10-08/full-game/GPT_DIVINATION_RANK3_SOURCE_CONFERENCE.md'
assert 'SOURCE-RECONCILED / DRAFTABLE' in (G/review).read_text(encoding='utf-8')
cat=read(R/'data/public/spell_playtests/catalog.json')['spells']
assert sum(bool(s['operational']) for s in cat)==190
assert not any(s['operational'] for s in cat if s['id'] in src)
minute="In initiative, expires at the caster's tenth future regular-start marker after application; outside initiative, expires 60 elapsed seconds after application. Preserve the original virtual marker or absolute deadline through initiative changes, absence, death and planar travel. An already-passed start never counts."
common=" Actual class access, repertoire, V/S/F components, costs, Dissonance/Refrain, beginning hooks, concentration transitions and interruption follow SPELL_INTEGRATION_RULES.md. Commit costs before the counter window; failed, blocked and countered effects do not refund costs or restore prior concentration. Use the actual casting class's school and rank. Specific information protections apply to their actual subjects and generating-source scope. Hidden unprotected facts are readable; undefined facts are not invented. No automatic scaling or generic upcast."
replace=" A successful replacement owns its new endpoint; stale cleanup cannot remove it. A failed or countered cast creates no replacement."
cards=[]
def add(id,ran,targets,duration,conc,resolution,effect,limits,notes):
    s=src[id]
    cards.append({'id':id,'activation':'Action','rangeFeet':ran,'targets':targets,'duration':duration,'concentration':conc,'components':['V','S','F'],'resolution':resolution,'effect':effect,'scaling':'None. No automatic increase in range, duration, targets, uses or information.','limitations':limits+common,'designNotes':notes,'implementationStatus':'LOCAL CANDIDATE — source-reconciled; exact manuscript review pending; not selectable','sourcePlacements':s['sourcePlacements'],'sourceCoreEntries':s['sourceCoreEntries'],'classAccessEvidence':s['classAccess'],'sourceReview':[review],'reviewEvidence':[]})

add('eyes-of-the-divine',60,
    'One creature whose current appearance you can see within 60 feet and line of effect.',
    'Instantaneous private visual inspection',False,
    'No save. Privately perceive the target’s current appearance with readable disguise layers identified and visually stripped away for you only. Mundane costume, cosmetics, mask, prosthetic disguise or similar actual concealment/impersonation reveals the undisguised current appearance beneath it. A magical visual disguise or illusion reveals the appearance beneath that effect.',
    'For an actual physical transformation, Polymorph or innate alternate form, perceive that the form is transformed only when that information is readable. If an actual current underlying/base-form record exists and is readable, see that form as a private overlay. An undefined or protected underlying appearance is Indeterminate; a protection also covering the presence of the transformation/disguise can withhold that fact too. Apply this independently through readable layers without inventing a root form beneath a permanently changed baseline. Ordinary clothes or appearance choices are not automatically disguises; the presentation must actually serve concealment/impersonation. The target’s physical appearance, body, gear and transformation remain unchanged for everyone.',
    'This grants no new sense for selecting an unseen creature. Blindness, darkness, smoke, Hidden, Invisible and other ordinary sight limits still matter unless a separate actual sense overcomes them; solid total cover blocks targeting. A creature you can actually see through another permitted sense remains eligible. The snapshot does not follow later disguise/form changes. No legal name, ancestry, class, statistics, alignment, motive, possession controller, history or prior-form chronology is disclosed. An overlay can support ordinary recognition or inference from the appearance, without certifying an unknown identity. No reversion, dispel, undressing, physical exposure or forced confession occurs.',
    'PRESERVED: Action/60 feet/V,S,F and seeing through magical and mundane disguises. NEW: one-creature instantaneous private inspection, actual sight gate, visual-layer stripping and underlying-form overlay. Exact completion applies protection independently to transformation presence and underlying form; it does not reveal protected transformation presence by default.')

add('future-echo',60,
    'Yourself and/or any willing allies you perceive within 60 feet and line of effect at resolution, each with an actual regular encounter initiative slot.',
    'Pending until the next numbered round boundary, then one affected round of initiative permutation; no concentration.',False,
    'No save. While an encounter initiative order exists, choose the eligible participants and record their desired relative order at resolution. Range, perception, willingness and allied status are checked then, with no later range tether. Outside initiative a legal cast has no scheduling effect and refunds no committed cost. This spell does not create initiative to manufacture a round. One pending Future Echo per caster; a later successful cast before execution replaces that caster’s pending schedule.',
    'After the current round’s final slot and normal end-round events finish, and before the next round’s first regular start, restore any prior round’s Future Echo permutation to the baseline, retaining changes made by other exact initiative rules. Then resolve pending Future Echo schedules in application order, with stable source/mechanical order breaking genuinely simultaneous ties. For each schedule, remove selected participants who no longer possess regular encounter slots and those already claimed by an earlier Future Echo at this boundary. Gather only the remaining participants’ own baseline slot positions, sort those positions earliest to latest, and assign those participants to them in the recorded relative order. Every remaining participant is claimed by that application even if a one-person set leaves its position unchanged. Enemy, unselected and skipped participants’ slots do not move. Removed participants’ abandoned baseline slots are not redistributed. Late entrants not selected at cast resolution are not added automatically. An Incapacitated participant retaining a regular slot remains in the permutation and obeys its actual restrictions.',
    'Each affected participant receives exactly one ordinary regular turn in the affected numbered round, with its normal movement, Action/Bonus Action permissions and regular-start Reaction refresh/recharge/death-save processing as applicable. The permutation itself creates no turn, Action, Reaction, recharge, save, pulse, fall step or recovery. Existing effects retain their previously recorded virtual markers, absolute deadlines and actual periodic clocks; a moved regular turn must not replay an already-scheduled fixed event. Effects newly created during the affected round use the actual schedule then in force. At the following boundary, the prior baseline resumes unless another exact initiative rule changes it; no midround restoration creates a duplicate or missing turn. Pending schedules can be countered, dispelled or suppressed only under an actual applicable rule. A pending schedule unavailable at its execution boundary expires without a delayed makeup. Boundary execution consumes the pending magic and records a fixed one-round turn assignment; later dispelling/suppressing that completed cast does not reverse an already-committed schedule midround. A fresh cast during the affected round can prepare the following round, after baseline restoration. Caster death alone does not erase an independent pending schedule, but a selected caster who loses their actual slot is filtered normally. Source-specific companion turns qualify only if they genuinely own regular slots, not merely for acting after an owner. Full Time Loop and its unimplemented runtime are not enabled by this manuscript.',
    'PRESERVED: Action/60 feet/V,S,F and choosing ally initiative order next round. NEW: willing selected set, permutation among existing slots for one round, no concentration, baseline restoration and first-application claims. Exact completions specify baseline-before-next-permutation ordering, singleton claims, suppression at the execution boundary and an atomic schedule commitment that cannot be dispelled into a broken midround order.')

add('reveal-weakness',60,
    'One creature you perceive within 60 feet and line of effect.',
    'Up to 1 minute or until consumed; no concentration. '+minute,False,
    'No initial save. The target’s next actual saving-throw event of any kind receives disadvantage. Consume this pending record immediately before that save resolves, even if another source already imposes disadvantage or advantage cancels it.',
    'Any event explicitly classified by its source as a saving throw qualifies, including a concentration save or death saving throw where those actual rules classify it as a save. Ability/tool checks, attack rolls and opposed checks do not qualify merely for resisting an effect. If an actual save resolves with an automatic result and no dice under its own source, consume the pending record without overriding that automatic result. If immunity or another rule means no saving throw occurs at all, the record is not consumed. A later permitted reroll belongs to the same original save event; use its actual replacement procedure without creating another Reveal Weakness use. One pending Reveal Weakness per target across all casters; a successful new application replaces the old record rather than banking another disadvantaged save.',
    'This does not force a saving throw, alter its DC, reveal target statistics or weaknesses, invent critical-save rules, undo a resolved result or prevent another independently legal reroll. Expiry without a save consumes no other resource and creates no delayed use. Protection from Scrying does not block this noninformational roll modifier merely because its generating school is Divination.'+replace,
    'PRESERVED: Action/60 feet/V,S,F and disadvantage on the target’s next saving throw without a printed initial save. NEW: finite one-minute pending window, all actual saving throws and cross-caster replacement. Exact completion distinguishes an automatic-result saving throw from an effect that creates no save event.')

add('planar-window',60,
    'One local fixed point or surface you perceive within 60 feet and line of effect, plus one intended specific location on a known plane other than your current plane.',
    'Concentration, up to 1 minute. '+minute,True,
    'No roll. Identify the remote location through prior personal visitation or a reliable map, description or established source that uniquely identifies it. Knowing a plane alone does not identify a site; no universal corresponding coordinates are invented. After costs commit, resolve the actual destination and applicable planar/information wards. If the remote designation has no usable viewpoint or is blocked, no readable remote information is supplied and no hidden reason is diagnosed. Neither viewpoint may occupy solid matter. The local point must have room for a nonphysical 5-foot-wide by 5-foot-high window.',
    'Create one fixed visible 5-by-5-foot viewing window. It displays ordinary vision from the fixed remote point in all directions; observers may direct their attention around that scene without moving the remote point. Anyone who can ordinarily see the local window can see the unprotected displayed scene. Local Blindness, actual visual obstructions and inability to see the window prevent this viewing. Remote light, darkness, smoke, walls and terrain work normally; the spell grants no darkvision or true sight. Separately, you privately detect the location and category of actual native beings and native ongoing effects/phenomena within 30 feet and line of effect of the remote point. Native means a genuine established native/origin relationship to that plane, supported by actual source or setting fiction. This added detection can locate a readable Hidden/Invisible native presence without providing sight of its body. A visitor or a spell merely cast there by a visitor is not thereby native. If a presence is otherwise visible through the window but its native provenance is undefined/protected, that classification is Indeterminate; it is not reported as nonnative. The additional detection does not reveal an otherwise unseen entity solely because its provenance is undefined. Protected presence/location/category fields remain protected independently.',
    'Only you receive native-detection reports; other observers receive the displayed ordinary vision. That private magical detection does not require your eyes or continued sight of the local window, but concentration and the remote 30-foot/line-of-effect limits still apply. Neither point moves, follows a creature/vehicle or searches rooms; ordinary translation of a chosen supporting surface does not carry the fixed window. No continuing 60-foot caster tether is added after legal placement, and no clock pauses on caster travel or suppression. One Planar Window per caster; successful recasting replaces it. Specific planar or information protections filter only their actual scope. The window is nonphysical magic, not a break in either barrier: no sound, passage, physical interaction, attack, remote target permission, line of effect or casting origin is supplied in either direction. It has no HP or harvestable surface and is affected only by an actually applicable detection/suppression/dispel rule. Suppression supplies no backlog or replay. The source’s remote visual scene is public, but it creates no recording object.'+replace,
    'PRESERVED: Action/V,S,F, vision into another plane and detection of native beings/effects. CONFLICT RULING: raw 60 feet is local placement; NEW concentration up to one minute replaces Instantaneous metadata. NEW: known remote location, fixed 5-by-5 public vision, private 30-foot native detection. Exact completions bound unknown-provenance reports to otherwise observed presences, distinguish private detection from eyesight, and add no unprinted continuing caster tether.')

add('speak-with-dead',60,
    'One perceived corpse or substantial apparent creature remains within 60 feet and line of effect; eligibility of its deceased identity and retained memories resolves after casting costs commit.',
    'Up to 1 minute or until five question exchanges are spent; no concentration. '+minute,False,
    'No save or willing-soul gate. After costs commit, determine whether these are sufficient actual remains of one currently dead creature identity to support an associated retained memory echo. Bones or equivalent substantial creature remains can qualify without an intact mouth, tongue or biological flesh. An active Undead/Construct, an ordinary broken device that was never a creature, identityless ash, a stray blood trace or old remains of a currently living identity do not qualify. If no readable qualifying echo exists, obtain no answers without learning which eligibility/protection fact failed.',
    'Invoke a retained memory echo associated with the addressed remains and deceased identity, not a soul, creature or resurrection. For this application you may spend up to five question exchanges. Each attempted materially unified inquiry and its answer uses one Action in initiative, or approximately six elapsed seconds outside initiative, and one question allowance; the original casting Action includes no free question. Distinct independent subquestions require their own exchanges, Actions and allowances even when spoken as one sentence. You must audibly address the remains from within 60 feet and line of effect; ordinary sound-blocking conditions apply. Each committed exchange spends its allowance even if the question is not understood or its answer is unknown/protected. The echo answers audibly from the remains, truthfully according to the deceased’s actual associated memories and beliefs before death. It uses a language the deceased knew and would reasonably use, with no automatic translation. If no mutually usable language or remembered answer supports a response, it may provide no intelligible answer, I do not know, I do not remember, or the appropriate equivalent. It cannot deliberately lie or withhold a known readable answer from hostility, but mistaken beliefs remain mistaken.',
    'Actual memories associated with the remains govern: this grants no post-death knowledge or automatic later-life memory update to an older fragment after resurrection and another death. Multiple fragments remain one deceased identity, not new people or duplicated souls. A fresh legal paid cast can ask another five; no daily immunity or exclusive global interview slot is added. Each application retains its own quota and deadline; asking an echo does not simultaneously question all other applications. The echo ends if the identity becomes living, the selected physical anchor no longer contains qualifying remains, the five exchanges are spent, or the spell expires/is actually ended. A temporary gap in speaking/range/sound/line of effect pauses no duration. Existing answers and ordinary remembered information persist after ending. Soul Bind or a resurrection-only blocker does not automatically block this memory echo; actual corpse, communication, memory or information protections keep their written scope. The spell generates Divination through Cleric, Mirrorsage, Ranger, Shaman, Wizard or Paladin, and Necromancy through Crimson Agent, Druid or Thief, exactly as the selected casting class’s access row states. A Divination-only ward cannot block a Necromancy cast merely because this shared identity has another school placement. Protection may also filter new information about a separately protected subject within its actual scope. No compelled living creature, identity creation, body animation, healing, resource refresh, skill/proficiency download, objective-history verification or usable recording token results.',
    'PRESERVED: both rank-three Divination/Necromancy source placements and five questions/answers; Core M/F uses shared F. NEW: retained-memory echo, substantial-remains eligibility, truthful subjective answers and one-minute interview. Exact completions put hidden eligibility after payment, require separate paid Action/question exchanges after casting, retain local audible inquiry/range, and bind memories to the actual associated remains rather than silently updating old fragments across later lives.')

add('faction-divination',0,
    'Self; choose one exact known canonical factionId.',
    'Instantaneous private institutional inquiry',False,
    'No roll. Privately learn one actual current major institutional objective of the chosen faction. No physical representative, positive reputation, membership, Faction Seal permission, geographic distance or planar anchor is required.',
    'A qualifying objective is a concrete established goal pursued or prioritized by the institution or its recognized governing authority, such as securing a trade route, recovering a stolen archive or removing a named governor from office. A member’s private wish, reputation inference or the Director’s preferred plot is not an institutional objective. If several objectives are genuinely coequal, the Director records one stable priority selection while that institutional state remains materially unchanged. Equivalent repeat casts across casters/rephrasing do not rotate through hidden coequal goals. Report No Current Major Objective only for genuine established absence; undefined or specifically protected institutional information reports Indeterminate. Independently readable portions of a meaningful goal may be stated while protected details remain Indeterminate, without identifying which ward or hidden record caused the limit.',
    'Protection of one leader’s personal information does not erase an independently established institutional objective, and a protected private plan does not become institutional merely to evade protection. A subfaction must have its own actual canonical identity to be selected separately; invented subdivisions are not extra inquiries. The spell does not directly reveal an operational plan, member list, exact locations, timetable, secret agents, resources or every subordinate objective. A goal can naturally mention a readable subject as necessary to make it concrete, but supplies no additional dossier. It changes neither reputation nor faction intent and forces no action.',
    'PRESERVED: Action/V,S,F/instantaneous and one current major faction objective. CONFLICT RULING: Self abstract informational casting replaces raw 60-foot metadata. NEW: exact institutional predicate, no geographic/planar anchor, stable coequal objective, and truthful absence versus undefined/protected output.')

add('alignment-revelation',60,
    'One creature you perceive within 60 feet and line of effect.',
    'Instantaneous public visual revelation',False,
    'The target makes a Charisma save against your spell DC. Success: no revelation. Failure: magic displays two self-luminous symbolic sigils immediately around the target, one for its actual Lawful/Neutral/Chaotic axis and one for its actual Good/Neutral/Evil axis. Each readable axis displays its true current value; each undefined or specifically protected axis displays Indeterminate. Only an exact masking rule can alter a displayed result.',
    'The sigils exist only during resolution, long enough to be ordinarily perceived, then vanish. An observer must actually be able to see the target to see and understand the corresponding symbolic revelation; no language or hearing is required. Blindness, solid visual obstruction or inability to see the target prevents that observation. The sigils emit no meaningful surrounding illumination and do not themselves grant sight of an Invisible/Hidden or otherwise unseen body. An observer who can see the target through another actual permitted sense can read them. The magic reveals the value; it does not make the target speak, confess, interpret a command or verify a lie.',
    'This grants no alignment change, behavior control, oathbreaking, compulsory PvP, crime/motive information or future-action guarantee. “True” does not silently bypass a written information protection. The failure creates only the public information event; known information is not erased when the sigils vanish. No automatic recording item, repeated-use immunity or daily cap is added. Its higher-rank price and CHA-save requirement remain despite overlap with lower-rank private readers; public disclosure is the reviewed distinction, not invented ward-piercing power.',
    'PRESERVED: Action/60 feet/V,S,F/instantaneous, true alignment revelation and CHA save negation. NEW: two publicly readable nonlinguistic sigils with actual observer sight requirements, independent readable/Indeterminate axes and no compelled speech. Relative balance against private lower-rank alignment spells remains open.')

add('resonance-sight-greater',0,
    'Self; magical effects within 60 feet on your plane and in line of effect.',
    'Instantaneous private snapshot',False,
    'No roll. Detect every currently existing qualifying magical effect with a readable portion in the area. Ordinary non-solid visual concealment and lack of mundane visibility, including Hidden/Invisible status, do not hide the effect itself. Solid total cover blocks the unreadable portion. This informational detection does not require ordinary visual sight of the effect.',
    'For each qualifying effect, privately receive its readable local location/footprint, actual effect/spell/property identity when explicitly established and unprotected (otherwise its established broad magical category), and recorded readable proximate generating source. Undefined/protected identity and provenance fields independently report Indeterminate, without erasing other readable fields. Proximate source means the specific originating spell cast/caster identity, item producing an active property, creature/feature producing an aura, or site/zone/ritual generating that effect. A locally qualifying effect can disclose its recorded source identity even when that source is now beyond 60 feet, but not that source’s current remote location, condition or inventory. Record source identity as it actually exists; a missing personal name is not invented. A footprint is clipped to the readable area, rather than exposing the entire remote extent of a partially local effect.',
    'Active intrinsic magic requires an actual presently active magical effect/aura record; a creature’s species/theme or RP pool alone is not one. A permanent item qualifies through a currently active property/effect, not a dormant historical enchantment with no active record. An existing ongoing record that is suppressed remains detectable as suppressed if that state is readable; an ended/removed effect or mere extinguished residue does not qualify. Resonance Tracking separately governs one-hour spell traces. A copy is identified as the actual copied effect and its proximate copying source, not a fresh original cast. Readable explicitly recorded provenance may identify the immediate source relationship but grants no independent recursive search through upstream controllers or histories. An attached aura can reveal its creature’s location through ordinary inference without granting sight of that body. Actual subject information protections can withhold attached-magic details, while independent environmental magic remains separately readable. No universal spell-rank/slot/charge/RP total, recipe, full stat block, dispel, control, extraction, copied spell, remote attack/casting origin or permanent map is granted. Remembering or writing a permitted snapshot uses ordinary memory and tools.',
    'PRESERVED: Action/V,S,F/instantaneous and all magical effects and their sources within 60 feet. CONFLICT RULING: Self with a 60-foot same-plane/line-of-effect sensing radius. NEW: local readable footprint, effect identity/category and proximate provenance, non-solid concealment bypass, actual ongoing suppressed versus ended/dormant distinctions and no direct remote-current-location report.')

assert len(cards)==8 and {s['id'] for s in cards}==set(src)
candidate={'status':'LOCAL CANDIDATE — SOURCE-RECONCILED; exact manuscript review pending; NOT SELECTABLE','scope':'Eight identities with rank-three Divination access; all nine original placements/Core blocks retained, including Speak with Dead’s actual Necromancy access. Tabletop manuscript only; runtime, balance and whole-game closure remain open.','reviewEvidence':[review],'spells':cards}
p=D/'candidate_divination_rank3.json'; assert not p.exists(); p.write_text(json.dumps(candidate,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
digest=sha(p)
intro='''# Eight rank-3 Divination spells — exact manuscript review

Please review these exact eight cards against your source conference and existing shared rules. Approve for manuscript promotion or specify exact required repairs. The selected catalog remains 190 reviewed / 658 unfinished until approval. All nine original placements/Core blocks and exact class access remain attached. This is not full runtime, numerical balance or whole-game certification. Please keep your reply below 17,000 characters.

Exact completions requiring particular attention:

1. Eyes of the Divine requires actual sight of the current appearance. It does not reveal that a transformation exists if that fact is itself protected; readable transformation presence and protected underlying appearance are handled independently. It reads actual current underlying/base-form records, not an invented former body beneath a permanently changed baseline.

2. Future Echo is no concentration and performs an atomic boundary permutation after current end-round events and prior Echo restoration. Each schedule claims remaining selected participants even if a singleton cannot move; later schedules use only their own remaining baseline slots. Caster death alone does not delete an independent pending schedule; the selected caster's lost slot is still filtered. A pending spell suppressed/unavailable at its one execution boundary expires without makeup. The executed magic is consumed into a fixed one-round scheduling decision, so later dispelling that completed cast cannot restore midround and duplicate/skip turns. Fresh Echo casts during that affected round can schedule the following round after baseline restoration. These anti-duplication details are NEW exact completions, not an implemented scheduler claim. Existing virtual durations/periodic/fall clocks stay fixed; actual regular turns still perform their normal one start/end process. Please confirm the cast-only-in-initiative/no-scheduling-outside language as authored.

3. Reveal Weakness consumes on an actual saving-throw event even if that source assigns an automatic result without dice; it changes no automatic result. An immunity that means no saving throw event at all does not consume it. Its one-minute window uses the established caster minute marker, with no initial save or invented exclusion of concentration/death saves that are actually classified as saving throws.

4. Planar Window's public scene is ordinary vision, including lighting and viewer Blindness. Native detection is a separate private magical location report: I have not required the caster to keep seeing the local window or added a continuing 60-foot tether. Caster travel does not move either point or pause its concentration clock. Please confirm or repair this interface. Unknown native provenance gives Indeterminate for an otherwise visible presence; it does not become a device for locating every invisible unknown-origin traveler. Genuine unprotected native presences still get the promised detection through non-solid concealment, clipped to remote 30 feet/LoE. Destination truth/wards are checked after payment; failed feeds do not diagnose a hidden reason. Both points are fixed in place, not portable scrying vehicles.

5. Speak with Dead uses post-payment eligibility for substantial apparent remains so an old body of a currently living identity does not become a free existence oracle. Casting includes no free question: five subsequent Action/exchanges fit within the one-minute window. Each independent subquestion needs its own Action and quota. Questions are audible from within 60 feet/LoE; each committed exchange spends its allowance even if untranslated, unknown or protected. The echo speaks known language without requiring a physical tongue. Multiple paid applications keep separate five-question ledgers; no extra exclusivity or daily immunity is added. Actual anchor destruction or return to life ends an interview. I bind knowledge to actual memories associated with these remains/death, so an old fragment is not automatically updated with a resurrected person's later life merely because they die again. Please explicitly approve or repair that fragment/knowledge boundary. Divination/Necromancy school remains the casting class's actual placement; no union.

6. Faction Divination can state a meaningful readable objective while an independently protected detail is Indeterminate; it cannot invent information or identify the blocking ward. It does not use a protected leader's private plan as a proxy for an established institutional goal.

7. Alignment Revelation keeps your observer-must-see-target interface even though the temporary sigils are self-luminous: they provide no new sight of an invisible body and no surrounding light. An actual other sense may enable ordinary seeing/reading. No linguistic or spoken confession is required.

8. Resonance Sight (Greater) handles actual ongoing suppressed records, not ended residue. Local footprints are clipped; a local effect's readable recorded proximate source may be remote, without disclosing its current location. It reports actual copying source, not an invented fresh original cast or an unlimited upstream search. Source identity has no guaranteed personal name when none is established. It reveals no separate universal rank/resource/charge/statblock package, though ordinary inference from a known spell name remains possible.

Please distinguish conditional repairs from approval. If approved I will preserve both Speak with Dead modes explicitly in the shared overlay, document Future Echo's bounded tabletop schedule and leave runtime integration open.

## Exact candidate

'''
fence=chr(96)*3
packet=intro+'Candidate byte SHA256: '+digest+'\n\n'+fence+'json\n'+json.dumps(candidate,indent=2,ensure_ascii=False)+'\n'+fence+'\n'
pp=A/'CODEX_DIVINATION_RANK3_EXACT_REVIEW.md'; assert not pp.exists(); pp.write_text(packet,encoding='utf-8')
sub={'status':'prepared for exact review; not promoted','ids':list(src),'candidatePath':str(p),'candidateSha256BeforeReview':digest,'packetPath':str(pp),'packetSha256':sha(pp),'operationalBefore':190,'unfinishedBefore':658,'classRulesSha256Before':sha(R/'docs/mechanics/CLASS_PLAYTEST_RULES.md'),'sourceHashLedgerBefore':read(R/'data/playtest/spell_sources/source_hashes.json')}
(A/'DIVINATION_RANK3_EXACT_SUBMISSION.json').write_text(json.dumps(sub,indent=2)+'\n',encoding='utf-8')
conf=read(A/'DIVINATION_RANK3_CONFERENCE_SUBMISSION.json'); conf.update({'status':'source conference complete; exact candidate prepared','sourceReviewEvidence':review,'sourceReviewTurnId':'375bb281-53d9-4ec0-9720-3806540ffe6e'})
(A/'DIVINATION_RANK3_CONFERENCE_SUBMISSION.json').write_text(json.dumps(conf,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'count':8,'sourcePlacements':9,'packetCharacters':len(packet),'candidateSha256':digest},indent=2))
